SELECT o.id, o.status, o.started_at, o.last_evidence_at, o.latest_signal_id, o.evidence_score, o.opportunity_health, o.execution_source, o.decision_code, o.executed_at, o.updated_at FROM execution_opportunity o WHERE o.symbol = 'EGLDUSDT' AND (o.started_at BETWEEN '2026-10-11 22:00:00' AND '2026-10-11 22:45:00' OR o.updated_at BETWEEN '2026-10-11 22:30:00' AND '2026-10-11 22:45:00') ORDER BY o.started_at LIMIT 20